//! Original-exponent physical JVP references from actual Torch vmap(func.jvp).
use ferro_core::{DType, Tensor};
use ferro_core::forward_ad::DualLevel;
#[derive(Clone,Copy)]
struct Golden {values:&'static[f64],shape:&'static[usize],stride:&'static[usize],f64:bool,live:bool,zero:bool}
struct Case {layout:usize,power:f64,wide:bool,enabled:bool,output:Option<Golden>,gradients:[Option<Golden>;2]}
fn tensor(values:&[f64],shape:&[usize],dtype:DType)->Tensor {Tensor::from_vec_f64(values.to_vec(),shape).unwrap().to_dtype(dtype)}
fn setup(layout:usize,wide:bool)->(Tensor,Tensor) {
    let x=match layout {
        0=>tensor(&[-2.],&[],DType::F32),1=>tensor(&[-2.,-0.,0.,2.],&[4],DType::F32),
        2=>tensor(&[-2.,0.,1.,-3.,2.,-1.,4.,-5.,0.,2.,-2.,1.],&[2,2,3],DType::F32).transpose(0,2).unwrap(),
        3=>Tensor::zeros(&[2,0,3]).transpose(0,2).unwrap(),
        4=>tensor(&[f64::NEG_INFINITY,-2.,-0.,0.,2.,f64::INFINITY,f64::NAN],&[7],DType::F32),_=>unreachable!(),
    }.requires_grad_(true).unwrap();
    let data=(0..2*x.numel()).map(|i|0.2+(i%5)as f64*0.1).collect::<Vec<_>>();let dtype=if wide{DType::F64}else{DType::F32};
    let d=if layout==2||layout==3 {tensor(&data,if layout==2{&[2,2,2,3]}else{&[2,2,0,3]},dtype).transpose(1,3).unwrap()}
        else {let mut shape=vec![2];shape.extend_from_slice(x.shape());tensor(&data,&shape,dtype)}.requires_grad_(true).unwrap();(x,d)
}
fn check(value:&Tensor,want:&Golden,context:&str) {
    assert_eq!(value.shape(),want.shape,"{context}:shape");assert_eq!(value.strides(),want.stride,"{context}:stride");
    assert_eq!(value.dtype(),if want.f64{DType::F64}else{DType::F32},"{context}:dtype");assert_eq!(value.requires_grad(),want.live,"{context}:live");assert_eq!(value.is_structural_zero(),want.zero,"{context}:zero");
    assert_eq!(value.numel(),want.values.len());if want.zero{return;}
    for (i,(v,w)) in value.to_vec_f64().into_iter().zip(want.values).enumerate() {
        assert!(v.is_nan()&&w.is_nan()||v==*w||v.is_finite()&&w.is_finite()&&(v-w).abs()<=4e-6*(1.+w.abs()),"{context}:value{i} {v}!={w}");
        if v==0.&&*w==0.{assert_eq!(v.is_sign_negative(),w.is_sign_negative(),"{context}:zero sign{i}");}
    }
}
#[test]
fn physical_scalar_power_matches_240_torch_original_exponent_cases() {
    let mut failures=vec![];
    for (index,case) in CASES.iter().enumerate() {
        if std::panic::catch_unwind(|| {
            let(x,d)=setup(case.layout,case.wide);
            let y=ferro_core::autograd::with_grad_enabled(case.enabled,|| {
                let level=DualLevel::functional_batched(&[&x],&[&d],2).unwrap();let primal=x.pow_scalar(case.power).unwrap();let tangent=level.batched_tangent(&primal).unwrap().unwrap();drop(level);tangent
            });
            let context=format!("case{index} layout{} p{:?} wide{} enabled{}",case.layout,case.power,case.wide,case.enabled);check(&y,case.output.as_ref().unwrap(),&context);
            assert_ne!(y._storage_ptr(),d._storage_ptr(),"{context}: tangent must be computed");
            if y.requires_grad() {
                let sum=y.sum();let one=if sum.dtype()==DType::F64{Tensor::from_vec_f64(vec![1.],&[]).unwrap()}else{Tensor::scalar(1.)};
                let gradients=Tensor::vjp_many_wrt_optional(&[&sum],&[&x,&d],&[&one],false).unwrap();
                for(i,(got,want))in gradients.iter().zip(&case.gradients).enumerate(){assert_eq!(got.is_some(),want.is_some(),"{context}: gradient{i} presence");if let(Some(got),Some(want))=(got,want){check(got,want,&format!("{context}:gradient{i}"));}}
            }
            assert!(x.grad().is_none()&&d.grad().is_none());
        }).is_err(){failures.push(index);}
    }
    assert!(failures.is_empty(),"failed actual Torch power cases {failures:?}");
}
#[test]
fn scalar_power_zero_preserves_normal_output_layout_without_changing_ordinary_vjp() {
    for dtype in[DType::F32,DType::F64] {for empty in[false,true] {
        let x=Tensor::ones(&[2,3]).transpose(0,1).unwrap();let x=if empty{x.narrow(0,0,0).unwrap()}else{x};let x=x.requires_grad_(true).unwrap();
        let seed=Tensor::ones(&[2,3]).transpose(0,1).unwrap();let seed=if empty{seed.narrow(0,0,0).unwrap()}else{seed};let seed=seed.to_dtype(dtype).requires_grad_(true).unwrap();
        let level=DualLevel::functional(&[&x],&[&seed]).unwrap();let primal=x.pow_scalar(0.).unwrap();let tangent=level.tangent(&primal).unwrap().unwrap();drop(level);
        assert_eq!(tangent.dtype(),DType::F32);assert_eq!(tangent.strides(),primal.strides());assert!(!tangent.requires_grad()&&!tangent.is_structural_zero());assert_ne!(tangent._storage_ptr(),primal._storage_ptr());
        let gradient=primal.sum().grad_wrt(&[&x],false).unwrap().remove(0);assert_eq!(gradient.strides(),[2,1]);assert!(!gradient.requires_grad());
    }}
}
